package com.interview.mysqlescdc.verifier.rebuild;
import java.sql.*;import java.util.concurrent.Semaphore;import javax.sql.DataSource;import org.springframework.jdbc.datasource.SingleConnectionDataSource;import org.springframework.stereotype.Component;import com.interview.mysqlescdc.verifier.source.*;
@Component public final class JdbcConsistentSourceScanner implements ConsistentSourceScanner {
 private static final int MAX_CURSORS=4;private final DataSource dataSource;private final IndependentExpectedProjector projector;private final Semaphore permits=new Semaphore(MAX_CURSORS);
 public JdbcConsistentSourceScanner(DataSource dataSource,IndependentExpectedProjector projector){this.dataSource=dataSource;this.projector=projector;}
 public SourceSnapshotCursor open(){if(!permits.tryAcquire())throw new IllegalStateException("too many source snapshot cursors");Connection c=null;try{c=dataSource.getConnection();c.setReadOnly(true);c.setAutoCommit(false);c.setTransactionIsolation(Connection.TRANSACTION_REPEATABLE_READ);try(var s=c.createStatement()){s.execute("START TRANSACTION WITH CONSISTENT SNAPSHOT");}var reader=new JdbcExpectedDocumentReader(org.springframework.jdbc.core.simple.JdbcClient.create(new SingleConnectionDataSource(c,true)),projector);return new Cursor(c,reader,permits);}catch(Exception e){if(c!=null)try{c.close();}catch(SQLException suppressed){e.addSuppressed(suppressed);}permits.release();throw new IllegalStateException("cannot open consistent source snapshot",e);}}
 private static final class Cursor implements SourceSnapshotCursor {private final Connection c;private final ExpectedDocumentReader reader;private final Semaphore permit;private boolean closed;Cursor(Connection c,ExpectedDocumentReader reader,Semaphore permit){this.c=c;this.reader=reader;this.permit=permit;}public synchronized ExpectedPage readAfter(long id,int size){if(closed)throw new IllegalStateException("snapshot cursor closed");try{return reader.readAfter(id,size);}catch(RuntimeException failure){try{close();}catch(RuntimeException closeFailure){failure.addSuppressed(closeFailure);}throw failure;}}@Override public synchronized void close(){if(closed)return;closed=true;RuntimeException failure=null;try{c.rollback();}catch(SQLException e){failure=new IllegalStateException("snapshot rollback failed",e);}try{c.close();}catch(SQLException e){var closeFailure=new IllegalStateException("snapshot connection close failed",e);if(failure==null)failure=closeFailure;else failure.addSuppressed(closeFailure);}finally{permit.release();}if(failure!=null)throw failure;}}
}
